response:
I assumed round 3's layout and interfaces carry over. Tickets are in spe/evals/tasks/tickets.jsonl. Each config's prompt and tool spec are in spe/sut/configs/<id>/. A mock tool runner at spe/sut/bin/tool logs each call to spe/runs/r04/calls/<trial>.jsonl. grade.py takes --answers, --in and --out. Trials run on Opus because the plan named no trial model.

**Gates before launch.** First, I check that `git log` shows the `SPE r04 predict` commit for spe/predictions/r04.yaml and spe/plans/r04.md, and that `git diff` shows neither file has changed since. Second, I run the grader selftest. grade.py must score the oracle at 50/50 on both label.category and label.priority. The oracle is answers.json rewritten as trial rows. grade.py must score empty labels and rotated wrong labels at 0/50. I also run judge.md on a few known-good and known-bad replies and confirm that the Opus judge sorts them correctly. Third, I regrade round 3's saved trial labels with this round's grade.py as a control. If the control numbers differ from round 3's recorded numbers, the grader changed, and I log that in spe/failures.md before going on. Fourth, I do a dry run with `only: ["B:T01", "C2:T01", "C2:T17"]`, `trials: 1` and `spend_cap_usd: 2`. The dry run must return schema-valid trials, a calls log for each trial, transcripts that the scan agent finds, a canary that fails in every grade batch, and zero peeks. I then set `est_usd` from the dry run's measured cost and set `transcripts_dir`. I pass `spend_cap_usd` as 40 minus what the gates spent. I commit the script as `SPE r04 evaluate (harness)` and launch. If any gate fails, I halt and report instead of launching.

```js
export const meta = {
  name: 'spe-round-eval',
  description: 'SPE eval of config B (12-line prompt, 6 tools) against config C2 (12-line prompt, 3 tools plus check_status) on 50 tickets, 5 trials per cell. Leak scan, code grade with canaries, top-up on split cells, blind Opus tone judge, failure analysis, completeness critic. Every paid call is checked against args.spend_cap_usd.',
  phases: [
    { title: 'Setup', detail: 'Load tickets and config prompts. Check config shape and hashes.' },
    { title: 'Trials', detail: 'Base trials in trial-major order, so a cap stop keeps cells even.' },
    { title: 'Scan', detail: 'Void any trial that touched spe/ outside its allowlist.' },
    { title: 'Grade', detail: 'grade.py on label.category and label.priority, one canary per batch.' },
    { title: 'Top-up', detail: 'Extra trials on split cells, capped, then scan and grade.' },
    { title: 'Judge', detail: 'Blind Opus tone judge per judge.md.' },
    { title: 'Synthesis', detail: 'Failure analysis and completeness critic.' },
  ],
};

// ---- Round and arguments ----
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const A = args ?? {};

const CONFIGS = A.configs ?? ['B', 'C2'];
const EXPECT = A.expect ?? {
  B: { prompt_lines: 12, tools: 6 },
  C2: { prompt_lines: 12, tools: 4, must_have: ['check_status'] },
};
const N_TICKETS = A.tickets ?? 50;
const TRIALS = A.trials ?? 5;
const ONLY = A.only ?? null;                 // dry run, e.g. ['B:T01', 'C2:T01']
const CAP = A.spend_cap_usd ?? 40;
const TAIL = A.tail_reserve_usd ?? 10;       // held back from trials for scan, grade, judge, synthesis
// Unmeasured defaults. The dry run replaces them through args.est_usd.
const EST = { setup: 0.3, trial: 0.05, scan: 0.15, grade: 0.1, judge: 0.08, synth: 0.6, ...(A.est_usd ?? {}) };
const SYNTH_RESERVE = 2 * EST.synth;
const PRICE = A.price_per_mtok ?? null;      // { in, out } USD per million tokens, for measured spend
const TOPUP_PER_CELL = A.topup_per_cell ?? 5;
const TOPUP_TOTAL = A.topup_total ?? 100;
const MAX_PEEK_RATE = A.max_peek_rate ?? 0.1;
const BATCH = A.batch ?? 20;
const SCAN_CHUNK = 40;
const GRADE_CHUNK = 25;
const JUDGE_CHUNK = 10;
const SEED = A.seed ?? ROUND;
const MODEL = { trial: A.trial_model ?? 'opus', judge: 'opus', harness: A.harness_model ?? 'opus' };
const TRANSCRIPTS = A.transcripts_dir;

const RUN = `spe/runs/${RR}`;
const P = {
  tickets: 'spe/evals/tasks/tickets.jsonl',
  answers: 'spe/evals/tasks/answers.json',
  grader: 'spe/evals/graders/grade.py',
  judge: 'spe/evals/graders/judge.md',
  sut: 'spe/sut',
  tool: 'spe/sut/bin/tool',
  failures: 'spe/failures.md',
  prediction: `spe/predictions/${RR}.yaml`,
};

if (!TRANSCRIPTS) throw new Error('args.transcripts_dir is required. The leak scan cannot run without it.');

// ---- Helpers ----
const trials = [];
const skipped = [];
let spentEst = 0;
let seq = 0;

const money = x => Math.round(x * 100) / 100;
const r3 = x => (x == null || Number.isNaN(x) ? null : Math.round(x * 1000) / 1000);
const mean = xs => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
const chunk = (xs, n) => { const out = []; for (let i = 0; i < xs.length; i += n) out.push(xs.slice(i, i + n)); return out; };

let rngState = (SEED >>> 0) || 1;
function rand() { rngState = (rngState * 1664525 + 1013904223) >>> 0; return rngState / 4294967296; }
function shuffle(xs) {
  const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; }
  return a;
}

function reserve(kind, what, limit) {
  const cost = EST[kind];
  if (spentEst + cost > limit) {
    skipped.push({ kind, what, est_usd: cost, spent_est_usd: money(spentEst), limit_usd: limit });
    log(`SKIP ${kind} ${what}: est $${cost} would pass $${limit} (est spent $${money(spentEst)})`);
    return false;
  }
  spentEst += cost;
  return true;
}

// A path is forbidden when it sits under spe/ and outside spe/sut/ and the trial's own work dir.
function forbidden(p, trialId) {
  const s = String(p).replace(/\\/g, '/');
  const m = s.match(/(?:^|\/)(spe\/.*)$/);
  if (!m) return false;
  const rel = m[1];
  return !(rel.startsWith(`${P.sut}/`) || rel.startsWith(`${RUN}/work/${trialId}/`));
}

const isCounted = r => r && r.status === 'ok' && !r.void && r.grade;
const labelOk = r => r.grade.category_ok && r.grade.priority_ok;

function halted(reason, extra = {}) {
  log(`HALT: ${reason}`);
  return { round: ROUND, status: 'halted', reason, spend_est_usd: money(spentEst), skipped, trials, ...extra };
}

async function runInBatches(items, fn, size, what) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    const part = items.slice(i, i + size);
    out.push(...(await parallel(part.map(it => () => fn(it)))));
    log(`${what}: ${Math.min(i + size, items.length)}/${items.length}, est spend $${money(spentEst)} of $${CAP}`);
  }
  return out;
}

// ---- Schemas ----
const SETUP_SCHEMA = {
  type: 'object',
  required: ['tickets', 'configs'],
  properties: {
    tickets: { type: 'array', items: { type: 'object', required: ['id', 'subject', 'body'],
      properties: { id: { type: 'string' }, subject: { type: 'string' }, body: { type: 'string' } } } },
    configs: { type: 'array', items: { type: 'object',
      required: ['id', 'prompt', 'tools', 'tools_json', 'prompt_lines', 'sha256_prompt', 'sha256_tools'],
      properties: {
        id: { type: 'string' }, prompt: { type: 'string' }, tools: { type: 'array', items: { type: 'string' } },
        tools_json: { type: 'string' }, prompt_lines: { type: 'integer' },
        sha256_prompt: { type: 'string' }, sha256_tools: { type: 'string' },
      } } },
  },
};

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['ticket_id', 'label', 'reply', 'files_read'],
  properties: {
    ticket_id: { type: 'string' },
    label: { type: 'object', required: ['category', 'priority'],
      properties: { category: { type: 'string' }, priority: { type: 'string' } } },
    reply: { type: 'string' },
    files_read: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: { results: { type: 'array', items: { type: 'object',
    required: ['trial_id', 'found', 'paths', 'tokens_in', 'tokens_out'],
    properties: {
      trial_id: { type: 'string' }, found: { type: 'boolean' },
      paths: { type: 'array', items: { type: 'string' } },
      tokens_in: { type: 'integer' }, tokens_out: { type: 'integer' },
    } } } },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['grader_error', 'results', 'missing_call_logs'],
  properties: {
    grader_error: { type: ['string', 'null'] },
    missing_call_logs: { type: 'array', items: { type: 'string' } },
    results: { type: 'array', items: { type: 'object',
      required: ['trial_id', 'category_ok', 'priority_ok', 'tool_calls', 'tool_errors'],
      properties: {
        trial_id: { type: 'string' }, category_ok: { type: 'boolean' }, priority_ok: { type: 'boolean' },
        tool_calls: { type: 'integer' }, tool_errors: { type: 'integer' },
      } } },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: { results: { type: 'array', items: { type: 'object',
    required: ['item_id', 'score', 'pass', 'reason'],
    properties: { item_id: { type: 'string' }, score: { type: 'number' }, pass: { type: 'boolean' }, reason: { type: 'string' } } } } },
};

const FA_SCHEMA = {
  type: 'object',
  required: ['failure_types'],
  properties: { failure_types: { type: 'array', items: { type: 'object',
    required: ['f_id', 'existing', 'name', 'kind', 'what', 'how_to_spot', 'seen_in', 'count_by_config', 'fix'],
    properties: {
      f_id: { type: 'string' }, existing: { type: 'boolean' }, name: { type: 'string' },
      kind: { type: 'string', enum: ['agent', 'tool', 'grader', 'answer key', 'judge', 'harness', 'task'] },
      what: { type: 'string' }, how_to_spot: { type: 'string' },
      seen_in: { type: 'array', items: { type: 'string' } },
      count_by_config: { type: 'object' }, fix: { type: 'string' },
    } } } },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps', 'unmeasured_predictions'],
  properties: {
    complete: { type: 'boolean' },
    unmeasured_predictions: { type: 'array', items: { type: 'string' } },
    gaps: { type: 'array', items: { type: 'object', required: ['what', 'severity', 'fix'],
      properties: { what: { type: 'string' },
        severity: { type: 'string', enum: ['blocks close-out', 'weakens a number', 'note'] },
        fix: { type: 'string' } } } },
  },
};

// ---- Setup ----
phase('Setup');
reserve('setup', 'setup', CAP);
let setup;
try {
  setup = await agent(
    `You are the harness setup step for SPE ${RR}. Read only these files:
- ${P.tickets}
- for each config id in ${JSON.stringify(CONFIGS)}: ${P.sut}/configs/<id>/prompt.md and ${P.sut}/configs/<id>/tools.json
Do not open ${P.answers}, anything under spe/evals/graders/, or anything under spe/predictions/.
Return:
- tickets: the first ${N_TICKETS} tickets in file order, with id, subject, and body copied character for character.
- configs: for each id, the full prompt.md text copied character for character, the tool names from tools.json, the full tools.json text, the line count of prompt.md from \`wc -l\`, and the sha256 of prompt.md and tools.json from \`shasum -a 256\`.`,
    { label: `${RR} setup`, phase: 'Setup', model: MODEL.harness, schema: SETUP_SCHEMA },
  );
} catch (e) {
  return halted(`setup failed: ${e?.message ?? e}`);
}

const problems = [];
if (setup.tickets.length !== N_TICKETS) problems.push(`expected ${N_TICKETS} tickets, got ${setup.tickets.length}`);
if (new Set(setup.tickets.map(t => t.id)).size !== setup.tickets.length) problems.push('duplicate ticket ids');
const CFG = {};
for (const id of CONFIGS) {
  const c = setup.configs.find(x => x.id === id);
  const want = EXPECT[id];
  if (!c) { problems.push(`config ${id} missing`); continue; }
  if (want && c.prompt_lines !== want.prompt_lines) problems.push(`${id}: prompt has ${c.prompt_lines} lines, expected ${want.prompt_lines}`);
  if (want && c.tools.length !== want.tools) problems.push(`${id}: ${c.tools.length} tools, expected ${want.tools}`);
  for (const t of want?.must_have ?? []) if (!c.tools.includes(t)) problems.push(`${id}: missing tool ${t}`);
  CFG[id] = c;
}
if (problems.length) return halted('setup check failed', { problems });
const configHashes = Object.fromEntries(CONFIGS.map(id => [id, { prompt: CFG[id].sha256_prompt, tools: CFG[id].sha256_tools }]));
log(`config hashes: ${JSON.stringify(configHashes)}`);

const TICKET = Object.fromEntries(setup.tickets.map(t => [t.id, t]));
let cells = [];
for (const t of setup.tickets) for (const c of CONFIGS) cells.push({ config: c, ticket: t });
if (ONLY) cells = cells.filter(x => ONLY.includes(`${x.config}:${x.ticket.id}`));
if (!cells.length) return halted('no cells selected');
log(`${cells.length} cells, ${TRIALS} base trials each, cap $${CAP}`);

// ---- Trial ----
function trialPrompt(cfg, ticket, trialId) {
  return `You are the support triage agent for one customer ticket. Follow the system prompt below exactly.

=== SYSTEM PROMPT ===
${cfg.prompt}
=== END SYSTEM PROMPT ===

You may call only these tools: ${cfg.tools.join(', ')}. Their specs:
${cfg.tools_json}

Call a tool by running this command. It prints the tool result as JSON.
  ${P.tool} --config ${cfg.id} --trial ${trialId} <tool_name> '<json args>'

File rules. You may read files only under ${P.sut}/ and ${RUN}/work/${trialId}/. Do not read, list, search, or open anything else under spe/. Do not run git commands. Do not look for answer keys, graders, or earlier results.

Ticket ${ticket.id}
Subject: ${ticket.subject}
Body:
${ticket.body}

When you finish, return the label (category and priority), the reply you would send the customer, and every file path you read.`;
}

async function runTrial(cell, kind) {
  const trialId = `${RR}-${cell.config}-${cell.ticket.id}-${String(++seq).padStart(4, '0')}`;
  if (!reserve('trial', trialId, CAP - TAIL)) return null;
  const rec = { trial_id: trialId, config: cell.config, ticket_id: cell.ticket.id, kind, status: 'ok' };
  const t0 = Date.now();
  try {
    rec.output = await agent(trialPrompt(CFG[cell.config], cell.ticket, trialId), {
      label: trialId, phase: kind === 'base' ? 'Trials' : 'Top-up', model: MODEL.trial, schema: TRIAL_SCHEMA,
    });
  } catch (e) {
    rec.status = 'harness_error';
    rec.error = String(e?.message ?? e).slice(0, 300);
  }
  rec.runtime_ms = Date.now() - t0;
  trials.push(rec);
  return rec;
}

// ---- Scan ----
function scanPrompt(ids) {
  return `You audit trial transcripts for SPE ${RR}. Transcripts are under ${TRANSCRIPTS}. Each transcript carries its trial id as its agent label.
For each trial id below, find its transcript. List every file or directory path the trial touched through any tool call. That includes Read, Grep, Glob, Edit, and Write, and Bash commands such as cat, head, tail, grep, rg, find, ls, python, and node. Copy each path as written and resolve relative paths against the repository root. Report any git command that prints file contents, such as git show or git log -p, as the path spe/<git-history>. Also sum input and output tokens from the transcript's usage records.
If you cannot find a transcript, set found to false. Do not decide whether a trial cheated. Only list paths.
Trial ids: ${JSON.stringify(ids)}`;
}

async function scan(recs, phaseName) {
  const ok = recs.filter(r => r && r.status === 'ok');
  for (const r of ok) {
    const bad = (r.output.files_read ?? []).filter(p => forbidden(p, r.trial_id));
    if (bad.length) { r.void = 'peeked'; r.peek_paths = bad; }
  }
  await runInBatches(chunk(ok, SCAN_CHUNK).map((g, i) => ({ g, i })), async ({ g, i }) => {
    const what = `${phaseName} scan ${i + 1}`;
    if (!reserve('scan', what, CAP - SYNTH_RESERVE)) { for (const r of g) r.void = r.void ?? 'unscanned'; return; }
    try {
      const res = await agent(scanPrompt(g.map(r => r.trial_id)), {
        label: `${RR} ${what}`, phase: phaseName, model: MODEL.harness, schema: SCAN_SCHEMA,
      });
      const byId = Object.fromEntries(res.results.map(x => [x.trial_id, x]));
      for (const r of g) {
        const s = byId[r.trial_id];
        if (!s || !s.found) { r.void = r.void ?? 'no_transcript'; continue; }
        r.tokens = { in: s.tokens_in, out: s.tokens_out };
        const bad = s.paths.filter(p => forbidden(p, r.trial_id));
        if (bad.length) { r.void = 'peeked'; r.peek_paths = [...new Set([...(r.peek_paths ?? []), ...bad])]; }
      }
    } catch (e) {
      for (const r of g) r.void = r.void ?? 'scan_error';
      log(`${what} failed: ${e?.message ?? e}`);
    }
  }, 5, `${phaseName} scan`);
}

// ---- Grade ----
function gradePrompt(batch, rows) {
  return `You run the code grader for SPE ${RR}, batch ${batch}. Do not grade anything by judgment.
1. Write the rows below as JSON Lines to ${RUN}/grade/${batch}.jsonl, one row per line, unchanged.
2. Run: python3 ${P.grader} --answers ${P.answers} --in ${RUN}/grade/${batch}.jsonl --out ${RUN}/grade/${batch}.graded.jsonl
3. Return category_ok and priority_ok for every trial_id exactly as grade.py wrote them.
4. For every trial_id, count the lines in ${RUN}/calls/<trial_id>.jsonl as tool_calls, and count the lines with a non-null "error" field as tool_errors. If the file is missing, use 0 and 0 and list the trial_id in missing_call_logs.
If grade.py exits nonzero or prints an error, put its exit code and stderr in grader_error and return no results. Otherwise set grader_error to null. Do not edit grade.py, answers.json, or the rows.
Rows:
${JSON.stringify(rows)}`;
}

async function grade(recs, phaseName, prefix) {
  const todo = recs.filter(r => r && r.status === 'ok' && !r.void);
  const errors = [];
  await runInBatches(chunk(todo, GRADE_CHUNK).map((g, i) => ({ g, i })), async ({ g, i }) => {
    const batch = `${prefix}-${String(i + 1).padStart(3, '0')}`;
    if (!reserve('grade', batch, CAP - SYNTH_RESERVE)) return;
    const canary = { trial_id: `${RR}-canary-${batch}`, ticket_id: g[0].ticket_id, config: 'canary',
      label: { category: '__canary__', priority: '__canary__' } };
    const rows = [...g.map(r => ({ trial_id: r.trial_id, ticket_id: r.ticket_id, config: r.config, label: r.output.label })), canary];
    try {
      const res = await agent(gradePrompt(batch, rows), {
        label: `${RR} grade ${batch}`, phase: phaseName, model: MODEL.harness, schema: GRADE_SCHEMA,
      });
      if (res.grader_error) { errors.push(`${batch}: ${res.grader_error}`); return; }
      const byId = Object.fromEntries(res.results.map(x => [x.trial_id, x]));
      const c = byId[canary.trial_id];
      if (!c || c.category_ok || c.priority_ok) { errors.push(`${batch}: canary did not fail`); return; }
      for (const r of g) {
        const x = byId[r.trial_id];
        if (!x) continue;
        r.grade = { category_ok: x.category_ok, priority_ok: x.priority_ok, tool_calls: x.tool_calls, tool_errors: x.tool_errors,
          call_log_missing: res.missing_call_logs.includes(r.trial_id) };
      }
    } catch (e) {
      errors.push(`${batch}: ${e?.message ?? e}`);
    }
  }, 5, `${phaseName} grade`);
  return errors;
}

// ---- Cell stats and summary ----
function cellStats(recs) {
  const m = {};
  for (const cell of cells) {
    m[`${cell.config}:${cell.ticket.id}`] = { config: cell.config, ticket_id: cell.ticket.id, attempted: 0,
      base_counted: 0, base_pass: 0, topup_counted: 0, topup_pass: 0 };
  }
  for (const r of recs) {
    const c = m[`${r.config}:${r.ticket_id}`];
    if (!c) continue;
    c.attempted++;
    if (!isCounted(r)) continue;
    const pass = labelOk(r);
    if (r.kind === 'base') { c.base_counted++; if (pass) c.base_pass++; } else { c.topup_counted++; if (pass) c.topup_pass++; }
  }
  return Object.values(m);
}

function summarize(recs) {
  const out = {};
  for (const c of CONFIGS) {
    const all = recs.filter(r => r.config === c);
    const done = all.filter(r => r.status === 'ok');
    const counted = done.filter(isCounted);
    const judged = counted.filter(r => r.tone);
    const calls = counted.reduce((a, r) => a + r.grade.tool_calls, 0);
    const errs = counted.reduce((a, r) => a + r.grade.tool_errors, 0);
    const withTok = counted.filter(r => r.tokens);
    out[c] = {
      attempted: all.length,
      completed: done.length,
      harness_errors: all.filter(r => r.status === 'harness_error').length,
      voided: done.filter(r => r.void).length,
      ungraded: done.filter(r => !r.void && !r.grade).length,
      counted: counted.length,
      label_acc: r3(mean(counted.map(r => (labelOk(r) ? 1 : 0)))),
      category_acc: r3(mean(counted.map(r => (r.grade.category_ok ? 1 : 0)))),
      priority_acc: r3(mean(counted.map(r => (r.grade.priority_ok ? 1 : 0)))),
      judged: judged.length,
      tone_pass_rate: r3(mean(judged.map(r => (r.tone.pass ? 1 : 0)))),
      tone_mean_score: r3(mean(judged.map(r => r.tone.score))),
      mean_tool_calls: counted.length ? r3(calls / counted.length) : null,
      tool_error_rate: calls ? r3(errs / calls) : null,
      mean_runtime_s: r3(mean(counted.map(r => r.runtime_ms / 1000))),
      mean_tokens_in: r3(mean(withTok.map(r => r.tokens.in))),
      mean_tokens_out: r3(mean(withTok.map(r => r.tokens.out))),
    };
  }
  return out;
}

// ---- Trials ----
phase('Trials');
const baseQueue = [];
for (let k = 1; k <= TRIALS; k++) for (const cell of cells) baseQueue.push(cell);
const base = await runInBatches(baseQueue, cell => runTrial(cell, 'base'), BATCH, 'base trials');

// ---- Scan ----
phase('Scan');
await scan(base, 'Scan');
const baseDone = base.filter(r => r && r.status === 'ok');
const peeks = baseDone.filter(r => r.void === 'peeked').length;
if (baseDone.length && peeks / baseDone.length > MAX_PEEK_RATE) {
  return halted(`peek rate ${peeks}/${baseDone.length} is above ${MAX_PEEK_RATE}. The sandbox may leak the answer key.`);
}

// ---- Grade ----
phase('Grade');
const gradeErrors = await grade(base, 'Grade', 'base');
if (gradeErrors.length) return halted('grader error', { grader_errors: gradeErrors });

// ---- Top-up ----
phase('Top-up');
const split = cellStats(trials).filter(c => c.base_counted > 0 && c.base_pass > 0 && c.base_pass < c.base_counted);
const topQueue = [];
for (let k = 1; k <= TOPUP_PER_CELL; k++) {
  for (const c of split) if (topQueue.length < TOPUP_TOTAL) topQueue.push({ config: c.config, ticket: TICKET[c.ticket_id] });
}
log(`${split.length} split cells, ${topQueue.length} top-up trials queued (cap ${TOPUP_PER_CELL} per cell, ${TOPUP_TOTAL} total)`);
const top = await runInBatches(topQueue, cell => runTrial(cell, 'topup'), BATCH, 'top-up trials');
await scan(top, 'Top-up');
const topErrors = await grade(top, 'Top-up', 'topup');
if (topErrors.length) return halted('grader error in top-up', { grader_errors: topErrors });

// ---- Judge ----
phase('Judge');
const toJudge = shuffle(trials.filter(isCounted));
const itemMap = {};
const items = toJudge.map((r, i) => {
  const id = `J${String(i + 1).padStart(4, '0')}`;
  itemMap[id] = r;
  const t = TICKET[r.ticket_id];
  return { item_id: id, ticket_subject: t.subject, ticket_body: t.body, reply: r.output.reply };
});
const judgeErrors = [];
await runInBatches(chunk(items, JUDGE_CHUNK).map((g, i) => ({ g, i })), async ({ g, i }) => {
  const what = `judge ${i + 1}`;
  if (!reserve('judge', what, CAP - SYNTH_RESERVE)) return;
  try {
    const res = await agent(
      `You are the tone judge for customer support replies. Read ${P.judge} and apply its rubric exactly. Read no other file under spe/.
Each item below has an opaque item_id, the customer's ticket, and the reply. You do not know which agent wrote a reply. Items come from several agents in random order. Score each reply on its own against the rubric, not against the other items. Judge tone only, as judge.md defines it. Do not judge whether the ticket was labeled correctly.
Return one result per item_id with the score, pass, and a one-sentence reason, using judge.md's scale and pass rule.
Items:
${JSON.stringify(g)}`,
      { label: `${RR} ${what}`, phase: 'Judge', model: MODEL.judge, schema: JUDGE_SCHEMA },
    );
    for (const x of res.results) if (itemMap[x.item_id]) itemMap[x.item_id].tone = { score: x.score, pass: x.pass, reason: x.reason };
  } catch (e) {
    judgeErrors.push(`${what}: ${e?.message ?? e}`);
  }
}, 10, 'judge');

// ---- Synthesis ----
phase('Synthesis');
const summaryBase = summarize(trials.filter(r => r.kind === 'base'));
const summaryAll = summarize(trials);
const cellTable = cellStats(trials);
const underCovered = cellTable.filter(c => c.base_counted < TRIALS).map(c => `${c.config}:${c.ticket_id} (${c.base_counted}/${TRIALS})`);
const voided = trials.filter(r => r.void).map(r => ({ trial_id: r.trial_id, reason: r.void, paths: r.peek_paths ?? [] }));
const harnessErrors = trials.filter(r => r.status === 'harness_error').map(r => ({ trial_id: r.trial_id, error: r.error }));
const judgeNote = 'The judge is Opus, the same model family as the trials. No cross-family judge was available, so shared blind spots are possible.';

const failing = trials.filter(isCounted).filter(r => !labelOk(r) || (r.tone && !r.tone.pass) || r.grade.tool_errors > 0)
  .map(r => ({ trial_id: r.trial_id, config: r.config, kind: r.kind, ticket_id: r.ticket_id, subject: TICKET[r.ticket_id].subject,
    label: r.output.label, category_ok: r.grade.category_ok, priority_ok: r.grade.priority_ok,
    tool_calls: r.grade.tool_calls, tool_errors: r.grade.tool_errors, tone: r.tone ?? null }));
const shown = failing.slice(0, 150);

const [failureAnalysis, completeness] = await parallel([
  async () => {
    if (!reserve('synth', 'failure analysis', CAP)) return null;
    try {
      return await agent(
        `You do the failure analysis for SPE ${RR}. Trials are finished, so you may read ${P.answers}, ${P.grader}, ${P.judge}, ${RUN}/calls/, ${RUN}/grade/, and ${P.failures}.
Group the failures below into failure types. Reuse an F-number from ${P.failures} when a failure matches an existing type. Number new types after the highest existing F-number. For each type give the name, kind, what happened, how to spot it, the trial ids it was seen in, the count per config, and a proposed fix. Check each label failure for a grader or answer-key bug before you blame the agent. A wrong answer key or a grade.py bug is its own failure type. Voided trials and harness errors are harness failures, not agent failures. Do not edit any file.
Failures (${failing.length} total, first ${shown.length} shown):
${JSON.stringify(shown)}
Voided trials: ${JSON.stringify(voided)}
Harness errors: ${JSON.stringify(harnessErrors)}`,
        { label: `${RR} failure analysis`, phase: 'Synthesis', model: MODEL.harness, schema: FA_SCHEMA },
      );
    } catch (e) { log(`failure analysis failed: ${e?.message ?? e}`); return null; }
  },
  async () => {
    if (!reserve('synth', 'completeness critic', CAP)) return null;
    try {
      return await agent(
        `You are the completeness critic for SPE ${RR}. Decide whether this run can support the close-out. You may read ${P.prediction}. Do not edit any file.
Check each item. Every predicted metric in ${P.prediction} has a measured number for every config in the base summary. Every selected cell has ${TRIALS} counted base trials or a logged reason. Every counted trial was graded and judged. Grader and judge errors are reported. Skipped calls are listed. Every voided trial has a reason. The judge note is present. List each gap with its severity and a fix.
Base summary: ${JSON.stringify(summaryBase)}
Summary with top-up: ${JSON.stringify(summaryAll)}
Selected cells: ${cells.length}. Under-covered cells: ${JSON.stringify(underCovered)}
Skipped calls: ${JSON.stringify(skipped)}
Voided: ${voided.length}. Harness errors: ${harnessErrors.length}. Judge errors: ${JSON.stringify(judgeErrors)}
Judge note: ${judgeNote}`,
        { label: `${RR} completeness critic`, phase: 'Synthesis', model: MODEL.harness, schema: CRITIC_SCHEMA },
      );
    } catch (e) { log(`completeness critic failed: ${e?.message ?? e}`); return null; }
  },
]);

let measuredTrialUsd = null;
if (PRICE) {
  measuredTrialUsd = money(trials.filter(r => r.tokens)
    .reduce((a, r) => a + (r.tokens.in * PRICE.in + r.tokens.out * PRICE.out) / 1e6, 0));
}

log(`done. est spend $${money(spentEst)} of $${CAP}, ${skipped.length} skipped calls, ${voided.length} voided, ${harnessErrors.length} harness errors`);

return {
  round: ROUND,
  status: 'complete',
  args_used: { configs: CONFIGS, tickets: N_TICKETS, trials: TRIALS, only: ONLY, cap_usd: CAP, tail_usd: TAIL, est_usd: EST,
    topup_per_cell: TOPUP_PER_CELL, topup_total: TOPUP_TOTAL, models: MODEL, seed: SEED },
  config_hashes: configHashes,
  spend: { cap_usd: CAP, est_usd: money(spentEst), measured_trial_usd: measuredTrialUsd },
  skipped,
  summary_base: summaryBase,          // compare these numbers with the prediction
  summary_with_topup: summaryAll,     // pooled, weighted toward split cells, report separately
  cells: cellTable,
  under_covered_cells: underCovered,
  voided,
  harness_errors: harnessErrors,
  judge_errors: judgeErrors,
  judge_note: judgeNote,
  failure_analysis: failureAnalysis,
  completeness,
  trials: trials.map(r => ({ trial_id: r.trial_id, config: r.config, ticket_id: r.ticket_id, kind: r.kind, status: r.status,
    void: r.void ?? null, label: r.output?.label ?? null, reply: r.output?.reply ?? null, grade: r.grade ?? null,
    tone: r.tone ?? null, runtime_ms: r.runtime_ms, tokens: r.tokens ?? null, error: r.error ?? null })),
};
